from datetime import datetime
from uuid import uuid4

from sqlalchemy import DateTime, Integer, String, text
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column


def new_uuid() -> str:
    """Generate a UUID string matching the ``CHAR(36)`` primary keys."""
    return str(uuid4())


class Base(DeclarativeBase):
    pass


class UUIDPrimaryKeyMixin:
    """``CHAR(36)`` primary key generated by the application before INSERT."""

    id: Mapped[str] = mapped_column(String(36), primary_key=True, default=new_uuid)


class TimestampMixin:
    """``DATETIME(6)`` created/updated timestamps mirroring the bootstrap DDL."""

    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=False),
        server_default=text("CURRENT_TIMESTAMP(6)"),
        nullable=False,
    )
    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=False),
        server_default=text("CURRENT_TIMESTAMP(6)"),
        server_onupdate=text("CURRENT_TIMESTAMP(6)"),
        nullable=False,
    )


class SoftDeleteMixin:
    deleted_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=False), nullable=True)


class RowVersionMixin:
    """Optimistic-locking counter; application increments it on sensitive updates."""

    row_version: Mapped[int] = mapped_column(Integer, nullable=False, server_default=text("1"))
